// offscreen identities are exercised by ordinary scrolling/clicking below.
const settle=page=>page.evaluate(async()=>{await document.fonts.ready;await Promise.allSettled([...document.images].filter(i=>{const r=i.getBoundingClientRect();return r.width&&r.height&&r.right>0&&r.left<innerWidth&&r.bottom>0&&r.top<innerHeight;}).map(i=>i.decode()));await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));});
