const setComputedText200=page=>page.evaluate(()=>{
 const root=document.querySelector('.mafia-online-shell');
 const saved=[root,...root.querySelectorAll('*')].map(node=>{const style=getComputedStyle(node);return{node,font:parseFloat(style.fontSize),line:parseFloat(style.lineHeight),inlineFont:node.style.getPropertyValue('font-size'),fontPriority:node.style.getPropertyPriority('font-size'),inlineLine:node.style.getPropertyValue('line-height'),linePriority:node.style.getPropertyPriority('line-height')};});
 for(const item of saved){if(Number.isFinite(item.font))item.node.style.setProperty('font-size',item.font*2+'px');if(Number.isFinite(item.line))item.node.style.setProperty('line-height',item.line*2+'px');}
 window.restoreMafiaTextScale=()=>{for(const item of saved){if(item.inlineFont)item.node.style.setProperty('font-size',item.inlineFont,item.fontPriority);else item.node.style.removeProperty('font-size');if(item.inlineLine)item.node.style.setProperty('line-height',item.inlineLine,item.linePriority);else item.node.style.removeProperty('line-height');}delete window.restoreMafiaTextScale;};
});
const measureNameReading=page=>page.locator('.mafia-seat-copy>b').evaluateAll(nodes=>nodes.map(node=>{
 const walker=document.createTreeWalker(node,NodeFilter.SHOW_TEXT),textRuns=[],words=[];
 while(walker.nextNode()){
  const text=walker.currentNode;if(!text.textContent.trim())continue;
  const style=getComputedStyle(text.parentElement);textRuns.push({text:text.textContent,fontSize:parseFloat(style.fontSize),lineHeight:style.lineHeight});
  for(const match of text.textContent.matchAll(/\S+/g)){const range=document.createRange();range.setStart(text,match.index);range.setEnd(text,match.index+match[0].length);words.push({text:match[0],lines:new Set([...range.getClientRects()].filter(r=>r.width>0).map(r=>Math.round(r.top))).size});}
 }
 const seat=node.closest('.mafia-seat');
 return{name:node.textContent,width:node.getBoundingClientRect().width,fontSize:parseFloat(getComputedStyle(node).fontSize),seatWidth:seat.getBoundingClientRect().width,seatFontSize:parseFloat(getComputedStyle(seat).fontSize),seatFlexBasis:getComputedStyle(seat).flexBasis,textRuns,words};
}));
